-- Additional sample experiences; THB remains the platform accounting currency.
ALTER TABLE journey_hub.venues ADD COLUMN city text NOT NULL DEFAULT 'Bangkok', ADD COLUMN country text NOT NULL DEFAULT 'Thailand', ADD COLUMN time_zone text NOT NULL DEFAULT 'Asia/Bangkok';
ALTER TABLE journey_hub.experiences ADD COLUMN details jsonb NOT NULL DEFAULT '{}'::jsonb;
SELECT 'sh-bund-'||to_char(d,'YYYYMMDD'),'sh-bund',(d+time '09:00') AT TIME ZONE 'Asia/Shanghai',((d+time '09:00') AT TIME ZONE 'Asia/Shanghai')+interval '120 minutes',12
FROM (SELECT (now() AT TIME ZONE 'Asia/Shanghai')::date+n AS d FROM generate_series(0,14) n) dates;
SELECT 'sh-oldtown-'||to_char(d,'YYYYMMDD'),'sh-oldtown',(d+time '12:00') AT TIME ZONE 'Asia/Shanghai',((d+time '12:00') AT TIME ZONE 'Asia/Shanghai')+interval '120 minutes',12
FROM (SELECT (now() AT TIME ZONE 'Asia/Shanghai')::date+n AS d FROM generate_series(0,14) n) dates;
SELECT 'sh-tea-'||to_char(d,'YYYYMMDD'),'sh-tea',(d+time '15:00') AT TIME ZONE 'Asia/Shanghai',((d+time '15:00') AT TIME ZONE 'Asia/Shanghai')+interval '90 minutes',12
FROM (SELECT (now() AT TIME ZONE 'Asia/Shanghai')::date+n AS d FROM generate_series(0,14) n) dates;
SELECT 'sg-marina-'||to_char(d,'YYYYMMDD'),'sg-marina',(d+time '17:00') AT TIME ZONE 'Asia/Singapore',((d+time '17:00') AT TIME ZONE 'Asia/Singapore')+interval '120 minutes',12
FROM (SELECT (now() AT TIME ZONE 'Asia/Singapore')::date+n AS d FROM generate_series(0,14) n) dates;
SELECT 'sg-chinatown-'||to_char(d,'YYYYMMDD'),'sg-chinatown',(d+time '12:00') AT TIME ZONE 'Asia/Singapore',((d+time '12:00') AT TIME ZONE 'Asia/Singapore')+interval '120 minutes',12
FROM (SELECT (now() AT TIME ZONE 'Asia/Singapore')::date+n AS d FROM generate_series(0,14) n) dates;
SELECT 'sg-kampong-'||to_char(d,'YYYYMMDD'),'sg-kampong',(d+time '09:00') AT TIME ZONE 'Asia/Singapore',((d+time '09:00') AT TIME ZONE 'Asia/Singapore')+interval '120 minutes',12
FROM (SELECT (now() AT TIME ZONE 'Asia/Singapore')::date+n AS d FROM generate_series(0,14) n) dates;
